-- Escuela Técnica N.º 35 Eduardo Latzina | Base relacional PostgreSQL / Supabase
-- Datos iniciales ficticios extraídos de la versión entregada. Corte histórico: 24/11/2026 (no incluye ese día).
-- Las tablas relacionales son un modelo complementario: el frontend existente continúa usando et35_workspace.
-- No incluye contraseñas ni crea cuentas de Supabase Auth. Las tablas se consultan desde SQL Editor / Table Editor.
BEGIN;
CREATE TABLE IF NOT EXISTS public.turnos (
 nombre text PRIMARY KEY,
 inicio time NOT NULL, fin time NOT NULL,
 normal_hasta time NOT NULL, tarde_desde time NOT NULL, tarde_hasta time NOT NULL,
 ausente_desde time NOT NULL, presencia_desde time NOT NULL,
 CHECK (inicio <= normal_hasta AND normal_hasta < tarde_desde AND tarde_desde <= tarde_hasta AND tarde_hasta < ausente_desde AND ausente_desde < presencia_desde AND presencia_desde < fin)
);
CREATE TABLE IF NOT EXISTS public.cursos (
 codigo text PRIMARY KEY, anio smallint NOT NULL CHECK (anio BETWEEN 1 AND 6),
 division smallint NOT NULL CHECK (division > 0), turno text NOT NULL REFERENCES public.turnos(nombre),
 especialidad text NOT NULL, UNIQUE (anio, division, especialidad)
);
CREATE TABLE IF NOT EXISTS public.alumnos (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 nombre text NOT NULL, apellido text NOT NULL, dni text NOT NULL UNIQUE,
 curso_codigo text NOT NULL REFERENCES public.cursos(codigo),
 email text, email_responsable text, codigo_qr text NOT NULL UNIQUE,
 fecha_alta date NOT NULL
);
CREATE TABLE IF NOT EXISTS public.preceptores (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 nombre text NOT NULL, apellido text NOT NULL, email text
);
CREATE TABLE IF NOT EXISTS public.usuarios (
 usuario text PRIMARY KEY, rol text NOT NULL CHECK (rol IN ('alumno','preceptor','jefa')),
 nombre text NOT NULL, apellido text NOT NULL,
 alumno_id bigint UNIQUE REFERENCES public.alumnos(id),
 preceptor_id bigint UNIQUE REFERENCES public.preceptores(id),
 auth_id uuid UNIQUE, activo boolean NOT NULL DEFAULT true,
 CHECK ((rol='alumno' AND alumno_id IS NOT NULL AND preceptor_id IS NULL) OR
 (rol='preceptor' AND preceptor_id IS NOT NULL AND alumno_id IS NULL) OR
 (rol='jefa' AND alumno_id IS NULL AND preceptor_id IS NULL))
);
CREATE TABLE IF NOT EXISTS public.asignaciones (
 curso_codigo text PRIMARY KEY REFERENCES public.cursos(codigo),
 preceptor_id bigint NOT NULL REFERENCES public.preceptores(id)
);
CREATE TABLE IF NOT EXISTS public.bimestres (
 anio smallint NOT NULL, numero smallint NOT NULL CHECK (numero BETWEEN 1 AND 4),
 inicio date NOT NULL, fin date NOT NULL, limite_faltas numeric(5,2) NOT NULL DEFAULT 5,
 PRIMARY KEY (anio,numero), CHECK (inicio <= fin), CHECK (limite_faltas > 0)
);
CREATE TABLE IF NOT EXISTS public.horarios (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 curso_codigo text NOT NULL REFERENCES public.cursos(codigo),
 dia_semana smallint NOT NULL CHECK (dia_semana BETWEEN 1 AND 5),
 sesion text NOT NULL CHECK (sesion IN ('principal','contraturno','educacion_fisica')),
 inicio time NOT NULL, fin time NOT NULL, observacion text,
 UNIQUE(curso_codigo,dia_semana,sesion), CHECK (inicio < fin)
);
CREATE TABLE IF NOT EXISTS public.calendario_escolar (
 fecha date PRIMARY KEY, motivo text NOT NULL, tipo text NOT NULL CHECK (tipo IN ('feriado','asueto','receso','suspension'))
);
CREATE TABLE IF NOT EXISTS public.asistencias (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 alumno_id bigint NOT NULL REFERENCES public.alumnos(id),
 fecha date NOT NULL, sesion text NOT NULL DEFAULT 'principal' CHECK (sesion IN ('principal','contraturno','educacion_fisica')),
 entrada time, salida time,
 estado text NOT NULL CHECK (estado IN ('Presente','Ausente','Tarde','Retiro','Justificado','Sin registrar')),
 tipo text NOT NULL, observacion text,
 es_simulado boolean NOT NULL DEFAULT false,
 UNIQUE(alumno_id,fecha,sesion), CHECK (salida IS NULL OR entrada IS NULL OR salida >= entrada)
);
CREATE TABLE IF NOT EXISTS public.justificaciones (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 asistencia_id bigint NOT NULL REFERENCES public.asistencias(id),
 tipo text NOT NULL CHECK (tipo IN ('medica','familiar','deportiva','otra')),
 motivo text NOT NULL DEFAULT '', estado text NOT NULL CHECK (estado IN ('En revisión','Justificado','Denegado')),
 observacion_revision text, archivo_nombre text, archivo_ruta text,
 presentado_por text REFERENCES public.usuarios(usuario), presentado_el timestamptz,
 revisado_por text REFERENCES public.usuarios(usuario), revisado_el timestamptz
);
CREATE UNIQUE INDEX IF NOT EXISTS et35_justificacion_vigente ON public.justificaciones(asistencia_id) WHERE estado IN ('En revisión','Justificado');
CREATE TABLE IF NOT EXISTS public.movimientos_matricula (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 alumno_id bigint NOT NULL REFERENCES public.alumnos(id), fecha date NOT NULL,
 tipo text NOT NULL CHECK (tipo IN ('baja','reingreso')), motivo text NOT NULL,
 usuario text REFERENCES public.usuarios(usuario)
);
CREATE TABLE IF NOT EXISTS public.ajustes_bimestrales (
 alumno_id bigint NOT NULL REFERENCES public.alumnos(id), anio smallint NOT NULL, bimestre smallint NOT NULL,
 valor numeric(6,2) NOT NULL CHECK (mod(valor,0.25)=0),
 PRIMARY KEY(alumno_id,anio,bimestre), FOREIGN KEY(anio,bimestre) REFERENCES public.bimestres(anio,numero)
);
CREATE TABLE IF NOT EXISTS public.registros_qr (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 asistencia_id bigint NOT NULL REFERENCES public.asistencias(id),
 movimiento text NOT NULL CHECK (movimiento IN ('Entrada','Salida')), registrado_el timestamptz NOT NULL DEFAULT now(),
 UNIQUE(asistencia_id,movimiento)
);
CREATE TABLE IF NOT EXISTS public.auditoria (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 fecha timestamptz NOT NULL DEFAULT now(), usuario text REFERENCES public.usuarios(usuario), accion text NOT NULL, detalle text
);
CREATE TABLE IF NOT EXISTS public.notificaciones (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 alumno_id bigint NOT NULL REFERENCES public.alumnos(id), usuario text REFERENCES public.usuarios(usuario),
 fecha timestamptz NOT NULL DEFAULT now(), email text, tipo text NOT NULL,
 estado text NOT NULL DEFAULT 'Borrador' CHECK (estado IN ('Borrador','Enviado','Error'))
);
CREATE INDEX IF NOT EXISTS et35_alumnos_curso ON public.alumnos(curso_codigo);
CREATE INDEX IF NOT EXISTS et35_alumnos_apellido ON public.alumnos(apellido);
CREATE INDEX IF NOT EXISTS et35_asistencias_fecha ON public.asistencias(fecha);
CREATE INDEX IF NOT EXISTS et35_matricula_alumno_fecha ON public.movimientos_matricula(alumno_id,fecha);

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- Historial inicial, extraído del generador de JavaScript. Se usa una tabla temporal para comprimir las filas.
-- Cada alumno ocupa dos caracteres: estado P/A/T/R/J y minuto de entrada relativo al comienzo del turno.
-- Los pares -- indican que no había registro (por ejemplo, ECPA para alumnos de otros años).
-- Las horas de tarde inválidas 13:60–13:69 del generador original se normalizan a 14:00–14:09.
CREATE TEMP TABLE et35_historial_inicial (fecha date PRIMARY KEY, datos text NOT NULL) ON COMMIT DROP;


WITH registros AS (
 SELECT a.id AS alumno_id, h.fecha, t.nombre AS turno, t.inicio, t.fin,
 substring(h.datos FROM (2*a.id-1)::integer FOR 1) AS marca,
 ascii(substring(h.datos FROM (2*a.id)::integer FOR 1))-65 AS minuto
 FROM et35_historial_inicial h CROSS JOIN public.alumnos a
 JOIN public.cursos c ON c.codigo=a.curso_codigo
 JOIN public.turnos t ON t.nombre=c.turno
 WHERE a.id BETWEEN 1 AND 2175 AND substring(h.datos FROM (2*a.id-1)::integer FOR 1) <> '-'
)
SELECT -(to_char(fecha,'YYYYMMDD')::bigint*10000+alumno_id), alumno_id,fecha,'principal',
 CASE WHEN marca IN ('A','J') THEN NULL ELSE (inicio + minuto*interval '1 minute')::time END,
 CASE WHEN marca IN ('A','J') THEN NULL WHEN marca='R' THEN CASE turno WHEN 'Noche' THEN time '20:00' WHEN 'Tarde' THEN time '16:00' ELSE time '10:30' END ELSE fin END,
 CASE marca WHEN 'P' THEN 'Presente' WHEN 'A' THEN 'Ausente' WHEN 'T' THEN 'Tarde' WHEN 'R' THEN 'Retiro' WHEN 'J' THEN 'Justificado' END,
 CASE marca WHEN 'A' THEN 'Sistema' WHEN 'J' THEN 'Justificación' WHEN 'R' THEN 'Manual' ELSE 'QR' END, true
FROM registros ON CONFLICT DO NOTHING;
-- Cinco solicitudes iniciales adaptadas a ausencias del historial 2026: las fechas de las solicitudes
-- de ejemplo antiguas (2025) no tenían registros correspondientes en el historial vigente.

ON CONFLICT DO NOTHING;

-- Las tablas de movimientos, QR reales, auditoría, ajustes y notificaciones quedan listas para operaciones futuras.
-- No se inventan escaneos físicos, bajas ni correos enviados.
CREATE OR REPLACE VIEW public.faltas_por_bimestre WITH (security_invoker=true) AS
SELECT a.id AS alumno_id,b.anio,b.numero AS bimestre,b.limite_faltas,
 greatest(0,coalesce(sum(CASE WHEN r.estado IN ('Ausente','Tarde') THEN
 (CASE WHEN r.sesion <> 'principal' OR EXISTS (
 SELECT 1 FROM public.horarios h WHERE h.curso_codigo=a.curso_codigo AND h.dia_semana=extract(isodow FROM r.fecha) AND h.sesion <> 'principal'
 ) THEN 0.5 ELSE 1 END) * (CASE WHEN r.estado='Tarde' THEN 0.5 ELSE 1 END)
 ELSE 0 END),0)+coalesce(aj.valor,0)) AS faltas
FROM public.alumnos a CROSS JOIN public.bimestres b
LEFT JOIN public.asistencias r ON r.alumno_id=a.id AND r.fecha BETWEEN b.inicio AND b.fin
LEFT JOIN public.ajustes_bimestrales aj ON aj.alumno_id=a.id AND aj.anio=b.anio AND aj.bimestre=b.numero
GROUP BY a.id,b.anio,b.numero,b.limite_faltas,aj.valor;
-- Mantiene las secuencias listas para nuevos registros después de la carga inicial.
SELECT setval(pg_get_serial_sequence('public.alumnos','id'),greatest(1,(SELECT max(id) FROM public.alumnos)),true);
SELECT setval(pg_get_serial_sequence('public.preceptores','id'),greatest(1,(SELECT max(id) FROM public.preceptores)),true);
SELECT setval(pg_get_serial_sequence('public.justificaciones','id'),greatest(1,(SELECT max(id) FROM public.justificaciones)),true);
SELECT setval(pg_get_serial_sequence('public.asistencias','id'),greatest(1,coalesce((SELECT max(id) FROM public.asistencias WHERE id>0),0)),true);
-- Las tablas nuevas no quedan expuestas a visitantes ni a usuarios autenticados sin políticas específicas.
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['turnos','cursos','alumnos','preceptores','usuarios','asignaciones','bimestres','horarios','calendario_escolar','asistencias','justificaciones','movimientos_matricula','ajustes_bimestrales','registros_qr','auditoria','notificaciones'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon, authenticated',t);
 END LOOP;
END $$;
REVOKE ALL ON public.faltas_por_bimestre FROM anon,authenticated;
-- Tabla de compatibilidad del sitio actual (sincronización JSON, requiere Supabase Auth).

create table if not exists public.et35_workspace (
  owner_id uuid primary key references auth.users(id) on delete cascade,
  version bigint not null default 1 check (version > 0),
  payload jsonb not null,
  modified_at timestamptz not null default now()
);
alter table public.et35_workspace enable row level security;
revoke all on public.et35_workspace from anon;
grant select, insert, update on public.et35_workspace to authenticated;
drop policy if exists "et35_read_own" on public.et35_workspace;
create policy "et35_read_own" on public.et35_workspace for select to authenticated
 using (owner_id = (select auth.uid()));
drop policy if exists "et35_insert_own" on public.et35_workspace;
create policy "et35_insert_own" on public.et35_workspace for insert to authenticated
 with check (owner_id = (select auth.uid()));
drop policy if exists "et35_update_own" on public.et35_workspace;
create policy "et35_update_own" on public.et35_workspace for update to authenticated
 using (owner_id = (select auth.uid()))
 with check (owner_id = (select auth.uid()));

COMMIT;
-- Comprobación de la carga inicial en SQL Editor:
SELECT 'cursos' AS tabla,count(*) AS registros FROM public.cursos
UNION ALL SELECT 'alumnos',count(*) FROM public.alumnos
UNION ALL SELECT 'preceptores',count(*) FROM public.preceptores
UNION ALL SELECT 'usuarios',count(*) FROM public.usuarios
UNION ALL SELECT 'asistencias',count(*) FROM public.asistencias
UNION ALL SELECT 'horarios',count(*) FROM public.horarios
UNION ALL SELECT 'justificaciones',count(*) FROM public.justificaciones;
